          }

          .dropdown-toggle:hover {
              background: rgba(255, 255, 255, 1);
              border-color: rgba(100, 149, 197, 0.4);
          }

          .dropdown-menu {
              position: absolute;
              top: calc(100% + 4px);
              right: 0px;
              min-width: 250px;
              background: white;
              border: 1px solid rgba(100, 149, 197, 0.2);
              border-radius: 8px;
